import assert from 'node:assert/strict';
import fs from 'node:fs';
const read=p=>fs.readFileSync(p,'utf8');
const list=read('components/admin-live/AdminLiveCustomersPanel.tsx');
const detail=read('components/admin-live/CustomerFullOrderHistory.tsx');
const api=read('app/api/admin-live/customer-lifetime/route.ts');
const access=read('app/api/admin-live/customer-access/route.ts');
const geo=read('lib/presenceWrite.ts');
assert.match(list,/fetch\('\/api\/admin-live\/customer-lifetime'/,'customer list must have its own full-history source independent of live broadcasts');
assert.match(list,/c\.orderCount=summary\.all/,'summary count must replace the recent 500-only approximation');
assert.match(list,/c\.paidAmount=summary\.paidAmount/,'summary payment must replace the recent 500-only amount');
assert.match(list,/c\.latestOrderAt=summary\.latestOrderAt/,'sorting by latest order should use full-history snapshot');
assert.match(list,/memberStatsReady \? money\(customer\.paidAmount\) : "…"/,'loading/error must never falsely display 0 KRW');
assert.match(list,/memberStatsReady && customer\.orderCount <= 0/,'buyer-only must operate on full-history count');
assert.match(list,/회원 상세 메뉴/,'accessible concise member detail tabs');
assert.match(list,/memberStatsReady \? b\.paidAmount/,'paid amount sorting is gated until full snapshot verified');
assert.match(list,/memberStatsReady \? b\.orderCount/,'order count sorting is gated until full snapshot verified');
assert.match(list,/MOVED mobile search before status\/sort filters|aria-label="고객 검색"/,'mobile search remains accessible');
assert.match(list,/MemberAccessHistory/,'existing IP history accessible in member drawer');
assert.match(detail,/calculateLifetimeStats\(rows \|\| \[\]\)/,'detail uses same grouped full-history classifier');
assert.match(api,/verifyAdminSessionFromRequest/,'PII summary must require admin session');
assert.match(api,/\.range\(from,from\+TABLE_PAGE_SIZE-1\)/,'historical orders are paginated until exhaustion');
assert.match(access,/verifyAdminSessionFromRequest/,'IP reader must require admin session');
assert.match(access,/validNames\.has\(name\)/,'do not attach unrelated visitor IPs to an account');
assert.match(geo,/regionFromVercelHeaders/,'new site visits use first-party geolocation, not guessed location');
assert.doesNotMatch(geo,/ip-api\.com|ipinfo\.io|ipwho\.is/,'no visitor IP sent to a third-party geolocation service');
console.log('PASS full-history customer list/details/filter/stats + protected IP history and first-party geo contracts');
